import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import { useCurrentTheme } from '../../../core/hooks/useCurrentTheme.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import { _generateVisualPresetCdnUrl } from '../empty-state-utils.js';

export interface EmptyStateVisualPresetProps extends StylingProps, DataTestId {
  /**
   * The visual context of the illustration.
   */
  context: 'chart' | 'document' | 'generic' | 'table' | 'query';
  /**
   * A visual cue added to the illustration hinting at the reason the state is empty.
   */
  type:
    | 'something-missing'
    | 'no-result'
    | 'something-wrong'
    | 'create-new'
    | 'no-permission';
}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.VisualPreset
 * @internal
 */
export function _isEmptyStateVisualPreset(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateVisualPresetProps> {
  return isElement(child) && child.type === VisualPreset;
}

/** Container for the Visual slot of the EmptyState component. */
export const VisualPreset = /* @__PURE__ */ forwardRef<
  HTMLImageElement,
  EmptyStateVisualPresetProps
>((props, forwardedRef) => {
  const {
    context,
    type,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  const currentTheme = useCurrentTheme();
  const visualPresetUrl = _generateVisualPresetCdnUrl(
    context,
    type,
    currentTheme,
  );

  return (
    // no meaningful alt text for screen readers
    // eslint-disable-next-line jsx-a11y/alt-text
    <img
      ref={forwardedRef}
      src={visualPresetUrl}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    />
  );
});

(VisualPreset as typeof VisualPreset & { displayName: string }).displayName =
  'EmptyState.VisualPreset';
